WITH TransactionsByAccount AS (SELECT account_id, MAX(amount) AS max_amount, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM transactions WHERE merchant NOT IN ('Grab', 'Shell', 'Lazada') GROUP BY account_id) SELECT a.id, a.account_type, a.opened_date, T.max_amount, T.merchant_values FROM accounts a LEFT JOIN TransactionsByAccount T ON a.id = T.account_id ORDER BY a.account_type DESC
